using System.Runtime.InteropServices;
using OcctSharp.Interop;
using OcctSharp.PolygonBoundaries;
using OcctSharp.PolyWorkspaces;
using OcctSharp.Values;
namespace OcctSharp.Runtime.Tests;
public sealed partial class PolygonBoundaryWorkspaceTests {
 static PolygonBoundaryWorkspaceTests()=>NativeLibraryResolver.EnsureRegistered(typeof(PolygonBoundaryWorkspaceTests).Assembly);
 static readonly Coordinates3d[] Points=[new(0,0,0),new(1,0,0),new(0,0,0)];
 static readonly double[] Parameters=[0,1,2];
 static readonly int[] FirstLoop=[0,1,2,0],SecondLoop=[5,6,7,5];
 [Fact]public void ExactMeshBoundaryLoopAndIndependentNativeCopies()=>OcctSharp.Tests.Shared.BatchAYBoundaryWorkflow.Run();
 [Theory][InlineData(false)][InlineData(true)]public void SpatialPolygonsCopyOptionalParametersAndDeflection(bool hasParameters){var points=Points.ToArray();var values=Parameters.ToArray();using var result=PolygonBoundaryWorkspaces.Spatial(points,hasParameters?values:null,.03);points[0]=new(5,5,5);values[0]=999;Assert.Equal(Points[0],result.Points[0]);Assert.Equal(.03,result.Deflection);Assert.Equal(hasParameters,result.HasParameters);if(hasParameters)Assert.Equal(Parameters,result.Parameters);else Assert.Null(result.Parameters);result.Dispose();Assert.Equal(Points[0],result.Points[0]);Assert.Throws<ObjectDisposedException>(()=>result.CopyTriangulation());}
 [Theory][InlineData(false)][InlineData(true)]public void TriangulationAssociationUsesExactCopiedIndexDomain(bool hasParameters){using var data=PolyDataWorkspaces.FromMesh(OcctSharp.Tests.Shared.BatchARMeshWorkflow.Square());using var native=data.CopyTriangulation();using var result=PolygonBoundaryWorkspaces.OnTriangulation(native,[0,1,0],hasParameters?Parameters:null);Assert.Equal(4,result.AssociatedTriangulationNodeCount);Assert.Equal(new[]{new Coordinates3d(0,0,0),new Coordinates3d(2,0,0),new Coordinates3d(0,0,0)},result.Points);native.Dispose();using var copy=result.CopyTriangulation();using var independent=PolyDataWorkspaces.Copy(copy);Assert.Equal(4,independent.Mesh.Positions.Count);}
 [Fact]public void SimpleNativeLoopsAreDeterministicAcrossInputOrdering(){DirectedPolygonLink[] links=[new(5,6),new(6,7),new(7,5),new(0,1),new(1,2),new(2,0)];using var a=PolygonBoundaryWorkspaces.SimpleLoops(links);using var b=PolygonBoundaryWorkspaces.SimpleLoops(links.Reverse());Assert.Equal(2,a.Loops.Count);Assert.Equal(FirstLoop,a.Loops[0]);Assert.Equal(SecondLoop,a.Loops[1]);Assert.Equal(a.Loops.SelectMany(x=>x),b.Loops.SelectMany(x=>x));}
 [Fact]public void BranchDuplicateHangingAndOppositeShortCyclesAreRejected(){Assert.ThrowsAny<Exception>(()=>PolygonBoundaryWorkspaces.SimpleLoops([new(0,1),new(1,2),new(1,3),new(2,0),new(3,0)]));Assert.ThrowsAny<Exception>(()=>PolygonBoundaryWorkspaces.SimpleLoops([new(0,1),new(1,2),new(2,3)]));Assert.ThrowsAny<Exception>(()=>PolygonBoundaryWorkspaces.SimpleLoops([new(0,1),new(1,2),new(2,0),new(0,1)]));Assert.ThrowsAny<Exception>(()=>PolygonBoundaryWorkspaces.SimpleLoops([new(0,1),new(1,0),new(2,3),new(3,2)]));}
 [Fact]public void InvalidPolygonValuesAndIndicesAreRejected(){Assert.ThrowsAny<Exception>(()=>PolygonBoundaryWorkspaces.Spatial(Points,[0]));Assert.ThrowsAny<Exception>(()=>PolygonBoundaryWorkspaces.Spatial([new(double.NaN,0,0),new(1,0,0)]));Assert.ThrowsAny<Exception>(()=>PolygonBoundaryWorkspaces.Spatial(Points,deflection:-1));using var data=PolyDataWorkspaces.FromMesh(OcctSharp.Tests.Shared.BatchARMeshWorkflow.Square());using var native=data.CopyTriangulation();Assert.ThrowsAny<Exception>(()=>PolygonBoundaryWorkspaces.OnTriangulation(native,[0,4]));Assert.ThrowsAny<Exception>(()=>PolygonBoundaryWorkspaces.OnTriangulation(native,[-1,0]));}
 [Fact]public unsafe void RawCapacityTypeAndStaleGuardsPreserveOutputs(){double* points=stackalloc double[6]{0,0,0,1,0,0};Assert.Equal(NativeStatus.Success,CreateNative(points,2,null,0,0,out var token));try{int* info=stackalloc int[7];double* values=stackalloc double[6];values[0]=999;Assert.NotEqual(NativeStatus.Success,PointsNative(token,values,5));Assert.Equal(999,values[0]);Assert.NotEqual(NativeStatus.Success,InfoNative(token,info,6,out _));Assert.NotEqual(NativeStatus.Success,TriNative(token,out var triangulation));Assert.Equal(0,triangulation);}finally{ReleaseNative(token);}int* output=stackalloc int[7];Assert.NotEqual(NativeStatus.Success,InfoNative(token,output,7,out _));Assert.NotEqual(NativeStatus.Success,InfoNative(0,output,7,out _));ReleaseNative(token);}
 [Fact]public void OversizedLazySequencesStopAtTheLimitAndDisposeEnumerators(){
  int linksRead=0;bool disposed=false;IEnumerable<DirectedPolygonLink> Links(){try{while(true){if(++linksRead>4097)throw new InvalidOperationException("Read beyond bounded links.");yield return new(0,1);}}finally{disposed=true;}}
  Assert.Throws<ArgumentOutOfRangeException>(()=>PolygonBoundaryWorkspaces.SimpleLoops(Links()));Assert.Equal(4097,linksRead);Assert.True(disposed);
  int parametersRead=0;IEnumerable<double> ParametersStream(){while(true){if(++parametersRead>3)throw new InvalidOperationException("Read beyond matching parameters.");yield return 0;}}
  Assert.Throws<ArgumentOutOfRangeException>(()=>PolygonBoundaryWorkspaces.Spatial(Points.Take(2),ParametersStream()));Assert.Equal(3,parametersRead);
 }
 [LibraryImport("OcctSharp.Native",EntryPoint="occtsharp_polygon_boundary_create3d")]private static unsafe partial NativeStatus CreateNative(double* points,int count,double* parameters,int has,double deflection,out nint token);
 [LibraryImport("OcctSharp.Native",EntryPoint="occtsharp_polygon_boundary_points")]private static unsafe partial NativeStatus PointsNative(nint token,double* values,int capacity);
 [LibraryImport("OcctSharp.Native",EntryPoint="occtsharp_polygon_boundary_info")]private static unsafe partial NativeStatus InfoNative(nint token,int* values,int capacity,out double deflection);
 [LibraryImport("OcctSharp.Native",EntryPoint="occtsharp_polygon_boundary_triangulation")]private static partial NativeStatus TriNative(nint token,out nint result);
 [LibraryImport("OcctSharp.Native",EntryPoint="occtsharp_polygon_boundary_release")]private static partial void ReleaseNative(nint token);
}
